CREATE TABLE IF NOT EXISTS library_lm_xv_kdp_structural_classifications_v1 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES library_documents(id), document_code TEXT NOT NULL, source_run_id TEXT NOT NULL, structural_detector_run_id TEXT NOT NULL, pdf_page INT NOT NULL, printed_page INT, page_status TEXT NOT NULL, document_part TEXT NOT NULL, structural_status TEXT NOT NULL, unit_type TEXT NOT NULL, unit_label TEXT, unit_number TEXT, evidence_quote TEXT, evidence_block_id UUID, evidence_bbox JSONB, detection_rule TEXT NOT NULL, confidence NUMERIC NOT NULL, review_status TEXT NOT NULL DEFAULT 'not_required', warnings JSONB NOT NULL DEFAULT '[]', raw_detection JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(structural_detector_run_id,pdf_page)
);
CREATE TABLE IF NOT EXISTS library_lm_xv_kdp_block_roles_v1 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES library_documents(id), source_run_id TEXT NOT NULL, structural_detector_run_id TEXT NOT NULL, pdf_page INT NOT NULL, block_id UUID REFERENCES library_lm_xv_kdp_page_blocks_v1(id), block_index INT NOT NULL, block_role_candidate TEXT NOT NULL, evidence_quote TEXT NOT NULL, bbox JSONB NOT NULL, confidence NUMERIC NOT NULL, warnings JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(structural_detector_run_id,pdf_page,block_index)
);
CREATE OR REPLACE VIEW library_lm_xv_kdp_structural_v1 AS SELECT * FROM library_lm_xv_kdp_structural_classifications_v1;
CREATE OR REPLACE VIEW library_lm_xv_kdp_search_ready_v2 AS SELECT p.*,s.document_part,s.structural_status,s.unit_type,s.unit_label,s.unit_number,s.evidence_quote,s.confidence,s.warnings AS structural_warnings FROM library_lm_xv_kdp_pages_v1 p JOIN library_lm_xv_kdp_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page AND s.source_run_id=p.source_run_id;
